import { useEffect, useState } from 'react';
import { useAuth } from '@/auth/context/auth-context';
import { useNavigate, useSearchParams } from 'react-router';
import { ROUTES } from '@/config/routes.config';
import { supabase } from '@/lib/supabase';

/**
 * Callback page for OAuth authentication redirects.
 * This component handles the authentication flow after a user signs in with a third-party provider.
 */
export function CallbackPage() {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const [error, setError] = useState<string | null>(null);
  const { saveAuth, setUser: setCurrentUser } = useAuth();

  useEffect(() => {
    // Get error parameters
    const errorParam = searchParams.get('error');
    const errorDescription = searchParams.get('error_description');

    if (errorParam) {
      setError(errorDescription || 'Authentication failed');
      // After a delay, redirect to signin page with error params
      setTimeout(() => {
        navigate(
          `${ROUTES.AUTH_SIGNIN}?error=${errorParam}&error_description=${encodeURIComponent(errorDescription || 'Authentication failed')}`,
        );
      }, 1500);
      return;
    }

    const handleCallback = async () => {
      try {
        const { data, error } = await supabase.auth.getSession();
        if (error) throw error;
        if (!data.session)
          throw new Error('Authentication session not established');

        // Navigate to the target page - AuthProvider will handle state updates via onAuthStateChange
        const nextPath = searchParams.get('next') || ROUTES.HOME;
        navigate(nextPath);
      } catch (err) {
        console.error('Error processing OAuth callback:', err);
        setError('An unexpected error occurred during authentication');
        setTimeout(
          () => navigate(`${ROUTES.AUTH_SIGNIN}?error=auth_callback_error`),
          1500,
        );
      }
    };

    handleCallback();
  }, [navigate, searchParams, saveAuth, setCurrentUser]);

  return (
    <div className="flex flex-col items-center justify-center min-h-screen p-4 text-center">
      {error ? (
        <div className="space-y-4">
          <h2 className="text-xl font-semibold text-destructive">
            Authentication Error
          </h2>
          <p className="text-muted-foreground">{error}</p>
          <p className="text-sm">Redirecting to sign-in page...</p>
        </div>
      ) : null}
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Link } from 'react-router';
import { toAbsoluteUrl } from '@/lib/helpers';
import { useSettings } from '@/providers/settings-provider';

const ResetPasswordCheckEmail = () => {
  const { settings } = useSettings();
  const [email, setEmail] = useState<string | null>(null);

  useEffect(() => {
    setEmail(new URLSearchParams(window.location.search).get('email'));
  }, []);

  return (
    <div className="card max-w-[440px] w-full">
      <div className="card-body p-10">
        <div className="flex justify-center py-10">
          <img
            src={toAbsoluteUrl('/media/illustrations/30.svg')}
            className="dark:hidden max-h-[130px]"
            alt=""
          />
          <img
            src={toAbsoluteUrl('/media/illustrations/30-dark.svg')}
            className="light:hidden max-h-[130px]"
            alt=""
          />
        </div>

        <h3 className="text-lg font-medium text-mono text-center mb-3">
          Check your email
        </h3>
        <div className="text-sm text-center text-secondary-foreground mb-7.5">
          Please click the link sent to your email{' '}
          <a
            href="#"
            className="text-sm text-foreground font-medium hover:text-primary-active"
          >
            {email}
          </a>
          <br />
          to reset your password. Thank you
        </div>

        <div className="flex justify-center mb-5">
          <Link
            to={
              settings?.layout === 'auth-branded'
                ? '/auth/reset-password/changed'
                : '/auth/classic/reset-password/changed'
            }
            className="btn btn-primary flex justify-center"
          >
            Skip for now
          </Link>
        </div>

        <div className="flex items-center justify-center gap-1">
          <span className="text-xs text-secondary-foreground">
            Didn’t receive an email?
          </span>
          <Link
            to={
              settings?.layout === 'auth-branded'
                ? '/auth/reset-password/enter-email'
                : '/auth/classic/reset-password/enter-email'
            }
            className="text-xs font-medium link"
          >
            Resend
          </Link>
        </div>
      </div>
    </div>
  );
};

export { ResetPasswordCheckEmail };

import { useEffect, useState } from 'react';
import { useAuth } from '@/auth/context/auth-context';
import { zodResolver } from '@hookform/resolvers/zod';
import {
  AlertCircle,
  Check,
  Eye,
  EyeOff,
  LoaderCircleIcon,
} from 'lucide-react';
import { useForm } from 'react-hook-form';
import { Link, useNavigate, useSearchParams } from 'react-router';
import { ROUTES } from '@/config/routes.config';
import { toAbsoluteUrl } from '@/lib/helpers';
import { Alert, AlertIcon, AlertTitle } from '@/components/ui/alert';
import { Button } from '@/components/ui/button';
import { Checkbox } from '@/components/ui/checkbox';
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from '@/components/ui/form';
import { Input } from '@/components/ui/input';
import { getSigninSchema, SigninSchemaType } from '../forms/signin-schema';

const TEST_ADMIN = {
  email: 'julian.gibbings+admin@gmail.com',
  password: 'Password123!',
};
const TEST_SUPPORT_WORKER = {
  email: 'julian.gibbings+supportworker@gmail.com',
  password: 'Password123!',
};
const TEST_SUPERVISOR = {
  email: 'julian.gibbings+supervisor@gmail.com',
  password: 'Password123!',
};
const TEST_HOUSE_MANAGER = {
  email: 'julian.gibbings+housemanager@gmail.com',
  password: 'Password123!',
};
const TEST_DIRECTOR = {
  email: 'julian.gibbings+director@gmail.com',
  password: 'Password123!',
};
const TEST_FINANCE = {
  email: 'julian.gibbings+finance@gmail.com',
  password: 'Password123!',
};

export function SignInPage() {
  const isProd = import.meta.env.VITE_APP_ENV === 'production';
  const isDev = !isProd;
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const { login, getUser, logout } = useAuth();
  const [passwordVisible, setPasswordVisible] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  // Check for success message from password reset or error messages
  useEffect(() => {
    const pwdReset = searchParams.get('pwd_reset');
    const errorParam = searchParams.get('error');
    const errorDescription = searchParams.get('error_description');

    if (pwdReset === 'success') {
      setSuccessMessage(
        'Your password has been successfully reset. You can now sign in with your new password.',
      );
    }

    if (errorParam) {
      switch (errorParam) {
        case 'auth_callback_failed':
          setError(
            errorDescription || 'Authentication failed. Please try again.',
          );
          break;
        case 'auth_callback_error':
          setError(
            errorDescription ||
              'An error occurred during authentication. Please try again.',
          );
          break;
        case 'auth_token_error':
          setError(
            errorDescription ||
              'Failed to set authentication session. Please try again.',
          );
          break;
        default:
          setError(
            errorDescription || 'Authentication error. Please try again.',
          );
          break;
      }
    }
  }, [searchParams]);

  const form = useForm<SigninSchemaType>({
    resolver: zodResolver(getSigninSchema()),
    defaultValues: {
      email: '',
      password: '',
      rememberMe: true,
    },
  });

  const loginAs = async (credentials: { email: string; password: string }) => {
    try {
      setIsProcessing(true);
      setError(null);

      // ENSURE CLEAN SLATE: Logout existing user and clear query cache
      await logout();

      await login(credentials.email, credentials.password);
      const user = await getUser();

      // NOTE: We ignore the 'next' parameter for Development buttons
      // to ensure the user lands on a page they actually have access to.
      if (user?.is_admin) {
        navigate(ROUTES.DASHBOARD);
      } else {
        navigate(ROUTES.MY_DASHBOARD);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Login failed');
    } finally {
      setIsProcessing(false);
    }
  };

  async function onSubmit(values: SigninSchemaType) {
    try {
      setIsProcessing(true);
      setError(null);

      // Simple validation
      if (!values.email.trim() || !values.password) {
        setError('Email and password are required');
        return;
      }

      // Sign in using the auth context
      await login(values.email, values.password);

      // Role-based redirect — read fresh user to avoid stale state
      const user = await getUser();

      const nextPath = searchParams.get('next');
      if (nextPath) {
        navigate(nextPath);
      } else if (user?.is_admin) {
        navigate(ROUTES.DASHBOARD);
      } else {
        navigate(ROUTES.MY_DASHBOARD);
      }
    } catch (err) {
      setError(
        err instanceof Error
          ? err.message
          : 'An unexpected error occurred. Please try again.',
      );
    } finally {
      setIsProcessing(false);
    }
  }

  return (
    <Form {...form}>
      <form
        onSubmit={form.handleSubmit(onSubmit)}
        className="block w-full space-y-5"
      >
        <div className="text-center space-y-1 pb-3">
          <img
            src={toAbsoluteUrl('/media/app/default-logo.png')}
            className="dark:hidden h-12 mx-auto mb-4"
            alt="InsideCare"
          />
          <img
            src={toAbsoluteUrl('/media/app/default-logo-dark.png')}
            className="light:hidden h-12 mx-auto mb-4"
            alt="InsideCare"
          />
          <h1 className="text-2xl font-semibold tracking-tight">Sign In</h1>
          <p className="text-sm text-muted-foreground">
            Welcome back! Log in with your credentials.
          </p>
        </div>

        {isDev && (
          <Alert variant="warning" appearance="light">
            <AlertIcon>
              <AlertCircle />
            </AlertIcon>
            <AlertTitle className="text-center">
              Development Environment - For testing only
            </AlertTitle>
          </Alert>
        )}

        {error && (
          <Alert
            variant="destructive"
            appearance="light"
            onClose={() => setError(null)}
          >
            <AlertIcon>
              <AlertCircle />
            </AlertIcon>
            <AlertTitle>{error}</AlertTitle>
          </Alert>
        )}

        {successMessage && (
          <Alert appearance="light" onClose={() => setSuccessMessage(null)}>
            <AlertIcon>
              <Check />
            </AlertIcon>
            <AlertTitle>{successMessage}</AlertTitle>
          </Alert>
        )}

        <FormField
          control={form.control}
          name="email"
          render={({ field }) => (
            <FormItem>
              <FormLabel>Email</FormLabel>
              <FormControl>
                <Input placeholder="Your email" {...field} />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />

        <FormField
          control={form.control}
          name="password"
          render={({ field }) => (
            <FormItem>
              <div className="flex justify-between items-center gap-2.5">
                <FormLabel>Password</FormLabel>
              </div>
              <div className="relative">
                <FormControl>
                  <Input
                    placeholder="Your password"
                    type={passwordVisible ? 'text' : 'password'} // Toggle input type
                    {...field}
                  />
                </FormControl>
                <Button
                  type="button"
                  variant="ghost"
                  mode="icon"
                  onClick={() => setPasswordVisible(!passwordVisible)}
                  className="absolute right-0 top-0 h-full px-3 py-2 hover:bg-transparent"
                >
                  {passwordVisible ? (
                    <EyeOff className="text-muted-foreground" />
                  ) : (
                    <Eye className="text-muted-foreground" />
                  )}
                </Button>
              </div>
              <FormMessage />
            </FormItem>
          )}
        />

        <FormField
          control={form.control}
          name="rememberMe"
          render={({ field }) => (
            <FormItem className="flex flex-col space-y-2">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <FormControl>
                    <Checkbox
                      checked={field.value}
                      onCheckedChange={field.onChange}
                    />
                  </FormControl>
                  <FormLabel className="text-sm font-normal cursor-pointer">
                    Remember me
                  </FormLabel>
                </div>
                <Link
                  to={ROUTES.AUTH_RESET_PASSWORD}
                  className="text-sm font-semibold text-foreground hover:text-primary"
                >
                  Forgot Password?
                </Link>
              </div>
            </FormItem>
          )}
        />

        <Button type="submit" className="w-full" disabled={isProcessing}>
          {isProcessing ? (
            <span className="flex items-center gap-2">
              <LoaderCircleIcon className="h-4 w-4 animate-spin" /> Loading...
            </span>
          ) : (
            'Sign In'
          )}
        </Button>

        {isDev && (
          <div className="border-t pt-4 mt-2">
            <p className="text-xs text-center text-muted-foreground mb-3 font-medium uppercase tracking-wide">
              Testing & Development
            </p>
            <div className="grid grid-cols-2 gap-2">
              <Button
                type="button"
                className="bg-purple-600 text-white hover:bg-purple-700 border-none"
                size="sm"
                onClick={() => loginAs(TEST_ADMIN)}
                disabled={isProcessing}
              >
                Admin
              </Button>
              <Button
                type="button"
                className="bg-blue-600 text-white hover:bg-blue-700 border-none"
                size="sm"
                onClick={() => loginAs(TEST_SUPPORT_WORKER)}
                disabled={isProcessing}
              >
                Support Worker
              </Button>
              <Button
                type="button"
                className="bg-emerald-600 text-white hover:bg-emerald-700 border-none"
                size="sm"
                onClick={() => loginAs(TEST_SUPERVISOR)}
                disabled={isProcessing}
              >
                Supervisor
              </Button>
              <Button
                type="button"
                className="bg-orange-600 text-white hover:bg-orange-700 border-none"
                size="sm"
                onClick={() => loginAs(TEST_HOUSE_MANAGER)}
                disabled={isProcessing}
              >
                House Manager
              </Button>
              <Button
                type="button"
                className="bg-cyan-600 text-white hover:bg-cyan-700 border-none"
                size="sm"
                onClick={() => loginAs(TEST_DIRECTOR)}
                disabled={isProcessing}
              >
                Director
              </Button>
              <Button
                type="button"
                className="bg-rose-600 text-white hover:bg-rose-700 border-none"
                size="sm"
                onClick={() => loginAs(TEST_FINANCE)}
                disabled={isProcessing}
              >
                Finance Manager
              </Button>
            </div>
          </div>
        )}
      </form>
    </Form>
  );
}

