/**
 * Dynamic description logic based on Module + Level
 */
export const getContextDescription = (
  moduleId: RBACModule,
  level: AccessLevel,
  moduleLabel?: string,
): { prefix: string; body: string } => {
  const label = moduleLabel || 'this module';

  if (level === ACCESS_LEVEL.NONE) {
    return {
      prefix: 'No Access',
      body: `to ${label}. Module is hidden and access is blocked.`,
    };
  }

  const isPersonal = [
    RBAC_MODULES.MY_ROSTER,
    RBAC_MODULES.MY_TIMESHEETS,
    RBAC_MODULES.MY_LEAVE,
    RBAC_MODULES.SHIFT_ROUTINES,
  ].includes(moduleId);

  const isManagement = [
    RBAC_MODULES.EMPLOYEES,
    RBAC_MODULES.STAFF_ONBOARDING,
    RBAC_MODULES.STAFF_COMPLIANCE,
    RBAC_MODULES.TIMESHEETS,
    RBAC_MODULES.LEAVE_REQUESTS,
    RBAC_MODULES.ROSTER_BOARD,
    RBAC_MODULES.INCIDENT_MANAGEMENT,
  ].includes(moduleId);

  const isOperational = [
    RBAC_MODULES.HOUSES,
    RBAC_MODULES.HOUSE_MANAGEMENT,
    RBAC_MODULES.HOUSE_OPERATIONS,
    RBAC_MODULES.HOUSE_CHECKLISTS,
    RBAC_MODULES.HOUSE_CHECKLIST_HISTORY,
    RBAC_MODULES.HOUSE_RESOURCES,
    RBAC_MODULES.HOUSE_STAFF,
  ].includes(moduleId);

  const isClinical = [
    RBAC_MODULES.PARTICIPANTS,
    RBAC_MODULES.PARTICIPANT_GOALS,
    RBAC_MODULES.PARTICIPANT_BEHAVIOUR,
    RBAC_MODULES.PARTICIPANT_SUPPORT_NEEDS,
    RBAC_MODULES.PARTICIPANT_MEALTIME,
    RBAC_MODULES.PARTICIPANT_MEDICAL_ROUTINE,
    RBAC_MODULES.PARTICIPANT_CLINICAL_TRACKERS,
    RBAC_MODULES.PARTICIPANT_MEDICATIONS,
    RBAC_MODULES.PARTICIPANT_EMERGENCY,
    RBAC_MODULES.PARTICIPANT_CONTACTS,
    RBAC_MODULES.PARTICIPANT_DOCUMENTS,
    RBAC_MODULES.PARTICIPANT_SHIFT_NOTES,
    RBAC_MODULES.PARTICIPANT_ACTIVITY_LOG,
  ].includes(moduleId);

  const isSystem = [
    RBAC_MODULES.ACCESS_CONTROL,
    RBAC_MODULES.MASTER_LISTS,
    RBAC_MODULES.ADMIN_COMPLIANCE,
    RBAC_MODULES.ADMIN_ONBOARDING,
    RBAC_MODULES.ACTIVITY_LOG,
    RBAC_MODULES.HOUSE_ACTIVITY_LOG,
  ].includes(moduleId);

  const isReporting = [
    RBAC_MODULES.REPORTING_CLINICAL,
    RBAC_MODULES.REPORTING_OPERATIONAL,
    RBAC_MODULES.REPORTING_COMPLIANCE,
  ].includes(moduleId);

  switch (level) {
    case ACCESS_LEVEL.FULL:
      return {
        prefix: 'Full Access',
        body: `to ${label} organization-wide.`,
      };
    case ACCESS_LEVEL.READ_ONLY:
      return {
        prefix: 'Read-only',
        body: `of ${label} organization-wide. No edits allowed.`,
      };
    case ACCESS_LEVEL.CONTEXT_READ_WRITE:
      if (isPersonal)
        return {
          prefix: 'Read/Write',
          body: `access limited to your own personal ${label} records.`,
        };
      if (isManagement)
        return {
          prefix: 'Read/Write',
          body: `of ${label} for direct reports or assigned house staff.`,
        };
      if (isClinical)
        return {
          prefix: 'Read/Write',
          body: `of ${label} for participants in your assigned houses.`,
        };
      if (isOperational)
        return {
          prefix: 'Read/Write',
          body: `management of ${label} within your assigned houses.`,
        };
      if (isSystem)
        return {
          prefix: 'Full Access',
          body: `to ${label} configurations and logs.`,
        };
      if (isReporting)
        return {
          prefix: 'Read/Write',
          body: `of ${label} reports for assigned houses and staff.`,
        };
      return {
        prefix: 'Read/Write',
        body: `context-aware access to ${label}.`,
      };
    case ACCESS_LEVEL.CONTEXT_READ_ONLY:
      if (isPersonal)
        return {
          prefix: 'View-only',
          body: `of your own personal ${label} records.`,
        };
      if (isManagement)
        return {
          prefix: 'View-only',
          body: `of ${label} for direct reports or assigned house staff.`,
        };
      if (isClinical)
        return {
          prefix: 'View-only',
          body: `of ${label} for participants in your assigned houses.`,
        };
      if (isOperational)
        return {
          prefix: 'View-only',
          body: `of ${label} within your assigned houses.`,
        };
      if (isSystem)
        return {
          prefix: 'View-only',
          body: `of ${label} logs and configurations.`,
        };
      if (isReporting)
        return {
          prefix: 'View-only',
          body: `of ${label} reports for assigned houses and staff.`,
        };
      return {
        prefix: 'View-only',
        body: `context-aware access to ${label}.`,
      };
    default:
      return { prefix: 'Restricted', body: `access to ${label}.` };
  }
};

const ACCESS_LEVELS: {
  value: AccessLevel;
  label: string;
  description: string;
}[] = [
  {
    value: ACCESS_LEVEL.FULL,
    label: 'Full Access',
    description: 'Global access to all records',
  },
  {
    value: ACCESS_LEVEL.CONTEXT_READ_WRITE,
    label: 'Context Read/Write',
    description: 'Locked to house/reports',
  },
  {
    value: ACCESS_LEVEL.CONTEXT_READ_ONLY,
    label: 'Context Read-Only',
    description: 'View locked to house/reports',
  },
  {
    value: ACCESS_LEVEL.READ_ONLY,
    label: 'Read-Only',
    description: 'Global View, No Edits',
  },
  {
    value: ACCESS_LEVEL.NONE,
    label: 'No Access',
    description: 'Hidden & Blocked',
  },
];

export function RolePermissionsMatrix() {
  const { roles = [] } = useRoles();
  const { data: allPermissions = [], isLoading } = useAllRolePermissions();
  const { mutateAsync: updatePermissions } = useUpdateRolePermissions();
  const { hasAccess } = useRBAC();

  const headerScrollRef = useRef<HTMLDivElement>(null);
  const bodyScrollRef = useRef<HTMLDivElement>(null);

  const handleHeaderScroll = (e: React.UIEvent<HTMLDivElement>) => {
    if (
      bodyScrollRef.current &&
      bodyScrollRef.current.scrollLeft !== e.currentTarget.scrollLeft
    ) {
      bodyScrollRef.current.scrollLeft = e.currentTarget.scrollLeft;
    }
  };

  const handleBodyScroll = (e: React.UIEvent<HTMLDivElement>) => {
    if (
      headerScrollRef.current &&
      headerScrollRef.current.scrollLeft !== e.currentTarget.scrollLeft
    ) {
      headerScrollRef.current.scrollLeft = e.currentTarget.scrollLeft;
    }
  };

  const canEdit = hasAccess({
    resource: RBAC_MODULES.ACCESS_CONTROL,
    requiredLevel: ACCESS_LEVEL.CONTEXT_READ_WRITE,
  });

  const activeRoles = roles.filter((r) => r.is_active);
  const [selectedRoleId, setSelectedRoleId] = useState<string>('');
  const [matrixSearch, setMatrixSearch] = useState('');

  const selectedRole = activeRoles.find((r) => r.id === selectedRoleId);
  const selectedPermissions = allPermissions.find(
    (p) => p.role_id === selectedRoleId,
  );

  // Determine if this is an Admin role based on access_control permissions
  const isAdminRole = selectedPermissions?.access_control === ACCESS_LEVEL.FULL;

  // Auto-select the first role when loaded
  useEffect(() => {
    if (!selectedRoleId && activeRoles.length > 0) {
      setSelectedRoleId(activeRoles[0].id);
    }
  }, [activeRoles, selectedRoleId]);

  const getPermission = (moduleId: string): AccessLevel => {
    if (!selectedRoleId) return ACCESS_LEVEL.NONE;
    const rolePerms = allPermissions.find((p) => p.role_id === selectedRoleId);
    if (!rolePerms) return ACCESS_LEVEL.NONE;
    return (rolePerms as any)[moduleId] || ACCESS_LEVEL.NONE;
  };

  const handleUpdate = async (moduleId: string, level: AccessLevel) => {
    if (!selectedRoleId || isAdminRole || !canEdit) return;
    try {
      await updatePermissions({
        role_id: selectedRoleId,
        updates: { [moduleId]: level } as any,
      });
      const levelLabel =
        ACCESS_LEVELS.find((l) => l.value === level)?.label || level;
      toast.success(`Access level set to ${levelLabel}`);
    } catch (error) {
      toast.error('Failed to save permissions');
    }
  };

  const handleBatchSectionUpdate = async (
    modules: ModuleConfig[],
    level: AccessLevel,
  ) => {
    if (!selectedRoleId || isAdminRole || !canEdit) return;

    const updates: Record<string, AccessLevel> = {};
    modules.forEach((mod) => {
      if (mod.id && !mod.isLabelOnly) {
        updates[mod.id] = level;
      }
    });

    if (Object.keys(updates).length === 0) return;

    try {
      await updatePermissions({
        role_id: selectedRoleId,
        updates: updates as any,
      });
      const levelLabel =
        ACCESS_LEVELS.find((l) => l.value === level)?.label || level;
      toast.success(`Set section access level to ${levelLabel}`);
    } catch (error) {
      toast.error('Failed to save section permissions');
    }
  };

  const filteredGroups = GROUPS.map((group) => {
    const matchedModules = group.modules.filter((m) =>
      m.label.toLowerCase().includes(matrixSearch.toLowerCase()),
    );
    return { ...group, modules: matchedModules };
  }).filter((group) => group.modules.length > 0);

  if (isLoading || !selectedRoleId) {
    return (
      <Card>
        <CardContent className="p-10 text-center text-gray-500">
          Loading permissions matrix...
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      {isAdminRole && (
        <Alert variant="warning" className="bg-amber-50 border-amber-200">
          <ShieldAlert className="size-4 text-amber-600" />
          <AlertTitle className="text-amber-800 font-bold">
            Admin Privileges Locked
          </AlertTitle>
          <AlertDescription className="text-amber-700">
            The {selectedRole?.role_name} role has system-wide override access.
            These permissions are locked and cannot be reduced. Certain personal
            modules (like Rosters and Timesheets) may not apply to full-time
            administrators.
          </AlertDescription>
        </Alert>
      )}

      <Card>
        <CardHeader className="flex flex-col sm:flex-row sm:items-end justify-between gap-4 py-5 border-b mb-0">
          <div className="flex flex-col gap-2 w-full sm:max-w-[350px]">
            <Label className="text-sm font-bold text-gray-700">
              Select Role to Edit
            </Label>
            <Select value={selectedRoleId} onValueChange={setSelectedRoleId}>
              <SelectTrigger className="h-10 border-primary focus:ring-primary">
                <SelectValue placeholder="-- Select a role to configure --" />
              </SelectTrigger>
              <SelectContent>
                {activeRoles.map((role) => (
                  <SelectItem key={role.id} value={role.id}>
                    {role.role_name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div className="relative w-full sm:max-w-[300px]">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 size-4 text-gray-400" />
            <Input
              placeholder="Search modules..."
              value={matrixSearch}
              onChange={(e) => setMatrixSearch(e.target.value)}
              className="pl-9 h-10 border-gray-200 focus:border-primary"
            />
          </div>
        </CardHeader>

        <CardContent className="p-0">
          <style>{`
            .scrollbar-none::-webkit-scrollbar {
              display: none;
            }
            .scrollbar-none {
              -ms-overflow-style: none;
              scrollbar-width: none;
            }
          `}</style>

          {/* Header Table (Sticky to Viewport) */}
          <div
            ref={headerScrollRef}
            onScroll={handleHeaderScroll}
            className="overflow-x-auto overflow-y-hidden border-b sticky top-[var(--header-height,70px)] z-[5] bg-gray-100 scrollbar-none"
          >
            <table className="w-[980px] border-separate border-spacing-0 table-layout-fixed caption-bottom text-foreground text-sm bg-gray-100">
              <colgroup>
                <col className="w-[280px]" />
                <col className="w-[140px]" />
                <col className="w-[140px]" />
                <col className="w-[140px]" />
                <col className="w-[140px]" />
                <col className="w-[140px]" />
              </colgroup>
              <thead>
                <tr className="bg-gray-100 border-b border-gray-200">
                  <th className="sticky left-0 z-[6] bg-gray-100 text-start font-bold text-gray-900 w-[280px] min-w-[280px] max-w-[280px] py-3.5 px-4 border-b border-r border-gray-200 shadow-[2px_0_5px_-2px_rgba(0,0,0,0.1)]">
                    Module
                  </th>
                  {ACCESS_LEVELS.map((level) => (
                    <th
                      key={level.value}
                      className="min-w-[140px] w-[140px] max-w-[140px] text-center py-3.5 px-4 border-b border-gray-200 bg-gray-100"
                    >
                      <div className="flex flex-col gap-0.5">
                        <span className="font-bold text-gray-900 text-xs">
                          {level.label}
                        </span>
                        <span className="text-[10px] uppercase tracking-wider text-gray-500 font-medium leading-none">
                          {level.description}
                        </span>
                      </div>
                    </th>
                  ))}
                </tr>
              </thead>
            </table>
          </div>

          {/* Body Table */}
          <div
            ref={bodyScrollRef}
            onScroll={handleBodyScroll}
            className="overflow-x-auto overflow-y-visible border-b relative"
          >
            <table className="w-[980px] border-separate border-spacing-0 table-layout-fixed caption-bottom text-foreground text-sm">
              <colgroup>
                <col className="w-[280px]" />
                <col className="w-[140px]" />
                <col className="w-[140px]" />
                <col className="w-[140px]" />
                <col className="w-[140px]" />
                <col className="w-[140px]" />
              </colgroup>
              <TableBody className="text-sm font-medium">
                {filteredGroups.map((group) => {
                  // Special logic for Houses group dependency
                  const isHousesGroup = group.title === 'Houses';
                  const houseProfilesLevel = getPermission(RBAC_MODULES.HOUSES);
                  const houseProfilesDisabled =
                    houseProfilesLevel === ACCESS_LEVEL.NONE;

                  // Special logic for Participant Records group dependency
                  const isParticipantsGroup =
                    group.title === 'Participant Records';
                  const participantProfilesLevel = getPermission(
                    RBAC_MODULES.PARTICIPANTS,
                  );
                  const participantProfilesDisabled =
                    participantProfilesLevel === ACCESS_LEVEL.NONE;

                  // Special logic for Employees group dependency
                  const isEmployeesGroup = group.title === 'Employees';
                  const staffProfilesLevel = getPermission(
                    RBAC_MODULES.EMPLOYEES,
                  );
                  const staffProfilesDisabled =
                    staffProfilesLevel === ACCESS_LEVEL.NONE;

                  return (
                    <Fragment key={group.title}>
                      <TableRow
                        key={`${group.title}-header`}
                        className="bg-gray-100/95 backdrop-blur-sm"
                      >
                        <TableCell className="sticky left-0 z-[2] bg-gray-100/95 backdrop-blur-sm py-2.5 pl-8 border-b border-r font-bold text-gray-900 text-xs uppercase tracking-wider">
                          {group.title}
                        </TableCell>
                        {ACCESS_LEVELS.map((level) => {
                          const validModules = group.modules.filter(
                            (m) => m.id && !m.isLabelOnly,
                          );
                          const isAllLevel =
                            validModules.length > 0 &&
                            validModules.every((m) => {
                              const current = getPermission(m.id!);
                              return isAdminRole
                                ? level.value === ACCESS_LEVEL.FULL
                                : current === level.value;
                            });

                          return (
                            <TableCell
                              key={level.value}
                              className="py-2.5 text-center border-b bg-gray-100/95 backdrop-blur-sm"
                            >
                              {canEdit ? (
                                <div className="flex justify-center">
                                  <Checkbox
                                    checked={isAllLevel}
                                    onCheckedChange={(checked) => {
                                      const targetLevel = checked
                                        ? level.value
                                        : ACCESS_LEVEL.NONE;
                                      handleBatchSectionUpdate(
                                        group.modules,
                                        targetLevel,
                                      );
                                    }}
                                    disabled={isAdminRole || !canEdit}
                                    className="size-5 border-gray-400 bg-white data-[state=checked]:bg-primary data-[state=checked]:border-primary transition-all cursor-pointer shadow-2xs"
                                    title={`Click to set all modules in ${group.title} to ${level.label}`}
                                  />
                                </div>
                              ) : null}
                            </TableCell>
                          );
                        })}
                      </TableRow>
                      {group.modules.map((module) => {
                        const currentLevel = module.id
                          ? getPermission(module.id)
                          : ACCESS_LEVEL.NONE;

                        // Dependency checks
                        const isLocked =
                          module.id &&
                          ((isHousesGroup &&
                            houseProfilesDisabled &&
                            module.id !== RBAC_MODULES.HOUSES) ||
                            (isParticipantsGroup &&
                              participantProfilesDisabled &&
                              module.id !== RBAC_MODULES.PARTICIPANTS) ||
                            (isEmployeesGroup &&
                              staffProfilesDisabled &&
                              module.id !== RBAC_MODULES.EMPLOYEES &&
                              module.isChild));

                        const desc = module.id
                          ? getContextDescription(
                              module.id,
                              isAdminRole ? ACCESS_LEVEL.FULL : currentLevel,
                              module.label,
                            )
                          : null;

                        return (
                          <TableRow
                            key={`${group.title}-${module.id || module.label}`}
                            className={cn(
                              'group hover:bg-gray-50/50 transition-colors',
                              isLocked && 'opacity-60 grayscale-[0.5]',
                              module.isLabelOnly &&
                                'bg-gray-100/95 hover:bg-gray-100/95 backdrop-blur-sm cursor-default',
                            )}
                          >
                            <TableCell
                              className={cn(
                                'py-4 sticky left-0 z-[2] bg-white group-hover:bg-[#fcfcfe] transition-colors border-r shadow-[2px_0_5px_-2px_rgba(0,0,0,0.05)]',
                                module.isChild ? 'pl-14' : 'pl-8',
                                module.isLabelOnly &&
                                  'bg-gray-100/95 py-2.5 pl-8 border-b font-bold text-gray-900 text-xs uppercase tracking-wider',
                              )}
                            >
                              <div className="flex flex-col">
                                <div className="flex items-center gap-2 text-wrap">
                                  <span
                                    className={cn(
                                      'font-semibold',
                                      module.isChild
                                        ? 'text-gray-600'
                                        : 'text-gray-700',
                                      module.isLabelOnly &&
                                        'text-gray-900 font-bold',
                                    )}
                                  >
                                    {module.label}
                                  </span>
                                  {isLocked && (
                                    <Badge
                                      variant="secondary"
                                      className="text-[10px] py-0 px-1.5 h-4 font-bold uppercase tracking-tight bg-gray-100 text-gray-400 border-none whitespace-nowrap"
                                    >
                                      LOCKED
                                    </Badge>
                                  )}
                                </div>
                                {!module.isLabelOnly && desc && (
                                  <div className="flex items-start gap-1 text-[11px] text-gray-400 mt-1 leading-relaxed">
                                    <Info className="size-3 mt-0.5 shrink-0" />
                                    <span>
                                      {isLocked ? (
                                        <span className="italic text-gray-400">
                                          Requires '
                                          {isHousesGroup
                                            ? 'Houses'
                                            : isParticipantsGroup
                                              ? 'Participant Profiles'
                                              : 'Staff Profiles'}
                                          ' access to be active.
                                        </span>
                                      ) : (
                                        <>
                                          <span className="font-bold text-gray-600">
                                            {desc.prefix}
                                          </span>{' '}
                                          {desc.body}
                                        </>
                                      )}
                                    </span>
                                  </div>
                                )}
                              </div>
                            </TableCell>
                            {ACCESS_LEVELS.map((level) => {
                              let isChecked = false;
                              let isDisabled = isAdminRole || !canEdit;

                              if (!module.isLabelOnly) {
                                isChecked = currentLevel === level.value;
                                if (isAdminRole) {
                                  isChecked = level.value === ACCESS_LEVEL.FULL;
                                }
                                isDisabled = isDisabled || isLocked;
                              } else if (module.label === 'Reporting') {
                                const reportingModuleIds = [
                                  RBAC_MODULES.REPORTING_CLINICAL,
                                  RBAC_MODULES.REPORTING_OPERATIONAL,
                                  RBAC_MODULES.REPORTING_COMPLIANCE,
                                ];
                                isChecked = reportingModuleIds.every((modId) => {
                                  const current = getPermission(modId);
                                  return isAdminRole
                                    ? level.value === ACCESS_LEVEL.FULL
                                    : current === level.value;
                                });
                              }

                              return (
                                <TableCell
                                  key={level.value}
                                  className={cn(
                                    'py-4 text-center border-b border-gray-100 last:border-r-0',
                                    module.isLabelOnly && 'py-2.5 bg-gray-100/95 backdrop-blur-sm',
                                  )}
                                >
                                  {(!module.isLabelOnly || module.label === 'Reporting') && (
                                    <div className="flex justify-center">
                                      <Checkbox
                                        checked={isChecked}
                                        onCheckedChange={(checked) => {
                                          if (isDisabled) return;
                                          if (!module.isLabelOnly) {
                                            if (!isChecked && module.id) {
                                              handleUpdate(module.id, level.value);
                                            }
                                          } else if (module.label === 'Reporting') {
                                            const targetLevel = checked
                                              ? level.value
                                              : ACCESS_LEVEL.NONE;
                                            const reportingModules = [
                                              { id: RBAC_MODULES.REPORTING_CLINICAL, label: 'Clinical Reports' },
                                              { id: RBAC_MODULES.REPORTING_OPERATIONAL, label: 'Operational Reports' },
                                              { id: RBAC_MODULES.REPORTING_COMPLIANCE, label: 'Compliance Reports' },
                                            ];
                                            handleBatchSectionUpdate(reportingModules, targetLevel);
                                          }
                                        }}
                                        disabled={isDisabled}
                                        className={cn(
                                          module.isLabelOnly
                                            ? 'size-5 border-gray-400 bg-white data-[state=checked]:bg-primary data-[state=checked]:border-primary transition-all cursor-pointer shadow-2xs'
                                            : 'size-5 border-gray-300 data-[state=checked]:bg-primary data-[state=checked]:border-primary transition-all',
                                          isDisabled && 'opacity-50 cursor-not-allowed',
                                        )}
                                        title={
                                          module.isLabelOnly
                                            ? `Click to set all modules in ${module.label} to ${level.label}`
                                            : undefined
                                        }
                                      />
                                    </div>
                                  )}
                                </TableCell>
                              );
                            })}
                          </TableRow>
                        );
                      })}
                    </Fragment>
                  );
                })}
              </TableBody>
            </table>
          </div>
        </CardContent>
        <CardFooter className="bg-gray-50/50 py-5 border-t text-sm text-gray-500 italic">
          Changes are saved automatically to the database when a checkbox is
          clicked.
        </CardFooter>
      </Card>
    </div>
  );
}

import { Fragment, useCallback, useEffect, useState } from 'react';
import { rosterApi } from '@/api/roster.api';
import { useAuth } from '@/auth/context/auth-context';
import {
  Toolbar,
  ToolbarDescription,
  ToolbarHeading,
  ToolbarPageTitle,
} from '@/partials/common/toolbar';
import { format } from 'date-fns';
import {
  AlertTriangle,
  CalendarClock,
  Check,
  Paperclip,
  X,
} from 'lucide-react';
import { Link } from 'react-router';
import { toast } from 'sonner';
import { RBAC_MODULES } from '@/config/rbac-modules';
import { ROUTES } from '@/config/routes.config';
import { STORAGE_BUCKETS } from '@/config/storage-buckets';
import { NotificationService } from '@/lib/notification-service';
import { ACCESS_LEVEL, useRBAC } from '@/hooks/useRBAC';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardTable } from '@/components/ui/card';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Label } from '@/components/ui/label';
import { SecureAvatar } from '@/components/ui/secure-avatar';
import { Textarea } from '@/components/ui/textarea';
import { Container } from '@/components/common/container';

const getInitials = (name?: string) => {
  if (!name) return '??';
  return name
    .split(' ')
    .map((n) => n[0])
    .join('')
    .toUpperCase()
    .slice(0, 2);
};

interface LeaveRequest {
  id: string;
  staff_id: string;
  leave_type_id: string;
  start_date: string;
  end_date: string;
  reason: string | null;
  status: 'pending' | 'approved' | 'rejected';
  admin_notes: string | null;
  attachment_url: string | null;
  created_at: string;
  staff: {
    id: string;
    staff_name: string;
    photo_url: string | null;
    auth_user_id: string | null;
  } | null;
  leave_type: { leave_type_name: string } | null;
  conflict_count?: number;
}

interface AffectedShift {
  id: string;
  start_date: string;
  start_time: string;
  end_time: string;
  house: { house_name: string } | null;
}

export function AdminLeaveRequestsPage() {
  const { user } = useAuth();
  const { hasAccess } = useRBAC();

  const canEdit = hasAccess({
    resource: RBAC_MODULES.LEAVE_REQUESTS,
    requiredLevel: ACCESS_LEVEL.CONTEXT_READ_WRITE,
  });

  const [requests, setRequests] = useState<LeaveRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [selected, setSelected] = useState<LeaveRequest | null>(null);
  const [action, setAction] = useState<'approve' | 'reject' | null>(null);
  const [adminNotes, setAdminNotes] = useState('');
  const [saving, setSaving] = useState(false);
  const [conflictCounts, setConflictCounts] = useState<Record<string, number>>(
    {},
  );
  const [affectedShifts, setAffectedShifts] = useState<AffectedShift[]>([]);
  const [shiftsLoading, setShiftsLoading] = useState(false);

  const statusVariant: Record<string, 'secondary' | 'success' | 'destructive'> =
    {
      pending: 'secondary',
      approved: 'success',
      rejected: 'destructive',
    };

  const statusLabel = {
    pending: 'Pending',
    approved: 'Approved',
    rejected: 'Rejected',
  };

  const dayCount = (req: LeaveRequest) => {
    const ms =
      new Date(req.end_date).getTime() - new Date(req.start_date).getTime();
    return Math.round(ms / 86400000) + 1;
  };

  const fetchRequests = useCallback(async () => {
    setLoading(true);
    try {
      const rows = (await rosterApi.listAdminLeaveRequests()) as LeaveRequest[];
      setRequests(rows);

      // Fetch conflict counts for all pending requests in a single bulk query
      const pending = rows.filter((r) => r.status === 'pending');
      if (pending.length > 0) {
        const staffIds = Array.from(new Set(pending.map((r) => r.staff_id)));
        const minDate = pending.reduce(
          (min, r) => (r.start_date < min ? r.start_date : min),
          pending[0].start_date,
        );
        const maxDate = pending.reduce(
          (max, r) => (r.end_date > max ? r.end_date : max),
          pending[0].end_date,
        );

        const allShifts = await rosterApi.listShiftsForStaffIds(
          staffIds,
          minDate,
          maxDate,
        );

        const counts: Record<string, number> = {};
        pending.forEach((req) => {
          const matches = (allShifts || []).filter(
            (s) =>
              s.staff_id === req.staff_id &&
              s.start_date >= req.start_date &&
              s.start_date <= req.end_date,
          );
          counts[req.id] = matches.length;
        });
        setConflictCounts(counts);
      }
    } catch (error) {
      console.error('Error loading leave requests:', error);
      toast.error('Failed to load leave requests');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchRequests();
  }, [fetchRequests]);

  const fetchAffectedShifts = async (
    staffId: string,
    startDate: string,
    endDate: string,
  ) => {
    setShiftsLoading(true);
    try {
      const data = await rosterApi.listConflictingShifts(
        staffId,
        startDate,
        endDate,
      );
      setAffectedShifts((data as AffectedShift[]) || []);
    } catch (err) {
      console.error('Error fetching affected shifts:', err);
    } finally {
      setShiftsLoading(false);
    }
  };

  const openAction = (req: LeaveRequest, type: 'approve' | 'reject') => {
    setSelected(req);
    setAction(type);
    setAdminNotes('');
    if (type === 'approve') {
      fetchAffectedShifts(req.staff_id, req.start_date, req.end_date);
    } else {
      setAffectedShifts([]);
    }
  };

  const handleAction = async () => {
    if (!selected || !action || !user) return;
    setSaving(true);
    const newStatus = action === 'approve' ? 'approved' : 'rejected';

    try {
      // Update the leave request
      await rosterApi.updateLeaveRequestStatus(
        selected.id,
        newStatus,
        adminNotes || null,
      );

      // Handle shift removal if approved
      if (newStatus === 'approved' && affectedShifts.length > 0) {
        // Mark shifts as 'open' (removing staff_id)
        const shiftIds = affectedShifts.map((s) => s.id);
        await rosterApi.bulkUpdateShifts(shiftIds, {
          staff_id: null,
          notes: `Staff member approved for leave. Previously assigned to ${selected.staff?.staff_name}.`,
        });
        toast.success(
          `Leave approved and ${affectedShifts.length} shifts opened.`,
        );
      }

      // Notify staff member via Edge Function or NotificationService
      if (selected.staff?.auth_user_id) {
        if (newStatus === 'approved') {
          await NotificationService.notifyLeaveApproved(
            selected.staff.auth_user_id,
            selected.start_date,
            selected.end_date,
          );
        } else if (newStatus === 'rejected') {
          await NotificationService.notifyLeaveRejected(
            selected.staff.auth_user_id,
            selected.start_date,
            selected.end_date,
            adminNotes || undefined,
          );
        }
      }

      if (newStatus === 'rejected' || affectedShifts.length === 0) {
        toast.success(`Leave request ${newStatus}`);
      }
      setSelected(null);
      setAction(null);
      fetchRequests();
    } catch (err) {
      console.error('Error handling leave action:', err);
      toast.error(`Failed to ${action} request`);
    } finally {
      setSaving(false);
    }
  };

  const handleView = async (filePath: string) => {
    if (!filePath) return;
    try {
      const url = await rosterApi.getStaffDocumentSignedUrl(filePath);
      if (url) window.open(url, '_blank');
    } catch (error) {
      console.error('Error viewing document:', error);
      toast.error('Failed to open document');
    }
  };

  return (
    <Fragment>
      <Container>
        <Toolbar>
          <ToolbarHeading>
            <ToolbarPageTitle text="Leave Management" />
            <ToolbarDescription>
              Review and approve staff leave requests
            </ToolbarDescription>
          </ToolbarHeading>
        </Toolbar>
      </Container>

      <Container>
        <div className="grid gap-5 lg:gap-7.5">
          {loading ? (
            <Card>
              <CardContent className="py-10 text-center text-sm text-muted-foreground">
                Loading requests...
              </CardContent>
            </Card>
          ) : requests.length === 0 ? (
            <Card>
              <CardContent className="py-16 text-center">
                <div className="flex size-14 items-center justify-center rounded-full bg-muted mx-auto mb-4">
                  <CalendarClock className="size-7 text-muted-foreground" />
                </div>
                <p className="text-gray-900 font-medium">
                  No leave requests found
                </p>
                <p className="text-sm text-gray-500 mt-1">
                  There are no leave requests needing review.
                </p>
              </CardContent>
            </Card>
          ) : (
            <Card>
              <CardTable>
                <table className="w-full text-left">
                  <thead>
                    <tr className="border-b border-gray-100 bg-gray-50/50">
                      <th className="px-5 py-3 text-xs font-bold uppercase text-muted-foreground">
                        Staff Member
                      </th>
                      <th className="px-5 py-3 text-xs font-bold uppercase text-muted-foreground">
                        Type
                      </th>
                      <th className="px-5 py-3 text-xs font-bold uppercase text-muted-foreground hidden sm:table-cell">
                        Dates
                      </th>
                      <th className="px-5 py-3 text-xs font-bold uppercase text-muted-foreground hidden md:table-cell">
                        Duration
                      </th>
                      <th className="px-5 py-3 text-xs font-bold uppercase text-muted-foreground hidden lg:table-cell">
                        Conflicts
                      </th>
                      <th className="px-5 py-3 text-xs font-bold uppercase text-muted-foreground">
                        Status
                      </th>
                      <th className="px-5 py-3 text-xs font-bold uppercase text-muted-foreground hidden md:table-cell">
                        Requested
                      </th>
                      <th className="px-5 py-3 text-xs font-bold uppercase text-muted-foreground">
                        Actions
                      </th>
                    </tr>
                  </thead>
                  <tbody>
                    {requests.map((req) => {
                      const isSelfRow = req.staff?.auth_user_id === user?.id;
                      return (
                        <tr
                          key={req.id}
                          className="border-b border-gray-50 group hover:bg-gray-50/50 transition-colors"
                        >
                          <td className="px-5 py-3.5">
                            {req.staff ? (
                              <Link
                                to={`${ROUTES.STAFF_DETAIL}/${req.staff.id}`}
                                className="flex items-center gap-3 group/staff w-fit"
                              >
                                <SecureAvatar
                                  src={req.staff.photo_url}
                                  initials={getInitials(req.staff.staff_name)}
                                  className="size-9 transition-all group-hover/staff:ring-2 group-hover/staff:ring-primary/20"
                                  bucket={STORAGE_BUCKETS.STAFF_PHOTOS}
                                />
                                <div className="flex flex-col">
                                  <span className="font-bold text-blue-700 dark:text-blue-400 group-hover/staff:underline transition-colors">
                                    {req.staff.staff_name}
                                  </span>
                                  <span className="text-[10px] text-muted-foreground truncate max-w-[150px]">
                                    {req.reason}
                                  </span>
                                </div>
                              </Link>
                            ) : (
                              <div className="flex flex-col">
                                <span className="font-bold text-gray-900">
                                  Unknown
                                </span>
                                <span className="text-[10px] text-muted-foreground truncate max-w-[150px]">
                                  {req.reason}
                                </span>
                              </div>
                            )}
                          </td>
                          <td className="px-5 py-3.5">
                            {req.leave_type?.leave_type_name ?? 'Leave'}
                          </td>
                          <td className="px-5 py-3.5 text-muted-foreground hidden sm:table-cell text-sm">
                            {format(new Date(req.start_date), 'dd MMM yyyy')}
                            {req.start_date !== req.end_date && (
                              <>
                                {' '}
                                –{' '}
                                {format(new Date(req.end_date), 'dd MMM yyyy')}
                              </>
                            )}
                          </td>
                          <td className="px-5 py-3.5 text-muted-foreground hidden md:table-cell text-sm">
                            {dayCount(req)} day{dayCount(req) !== 1 ? 's' : ''}
                          </td>
                          <td className="px-5 py-3.5 hidden lg:table-cell">
                            {req.status === 'pending' &&
                            conflictCounts[req.id] != null ? (
                              conflictCounts[req.id] > 0 ? (
                                <Badge variant="warning" appearance="light">
                                  {conflictCounts[req.id]} shift
                                  {conflictCounts[req.id] !== 1 ? 's' : ''}
                                </Badge>
                              ) : (
                                <span className="text-muted-foreground/50 text-xs">
                                  None
                                </span>
                              )
                            ) : (
                              <span className="text-muted-foreground/50 text-xs">
                                —
                              </span>
                            )}
                          </td>
                          <td className="px-5 py-3.5">
                            <Badge
                              variant={statusVariant[req.status] ?? 'secondary'}
                              appearance="light"
                              size="sm"
                            >
                              {statusLabel[req.status] ?? req.status}
                            </Badge>
                          </td>
                          <td className="px-5 py-3.5 text-muted-foreground hidden md:table-cell text-xs">
                            {format(new Date(req.created_at), 'dd MMM yyyy')}
                          </td>
                          <td className="px-5 py-3.5">
                            {req.status === 'pending' && (
                              <div className="flex items-center gap-1">
                                <Button
                                  size="sm"
                                  className="h-7 px-2.5 text-xs"
                                  onClick={() => openAction(req, 'approve')}
                                  disabled={isSelfRow || !canEdit}
                                  title={
                                    isSelfRow
                                      ? 'Cannot approve your own leave'
                                      : !canEdit
                                        ? 'Insufficient permissions'
                                        : 'Approve'
                                  }
                                >
                                  <Check className="size-3.5 me-1" /> Approve
                                </Button>
                                <Button
                                  size="sm"
                                  variant="destructive"
                                  className="h-7 px-2.5 text-xs"
                                  onClick={() => openAction(req, 'reject')}
                                  disabled={!canEdit}
                                  title={
                                    !canEdit
                                      ? 'Insufficient permissions'
                                      : 'Reject'
                                  }
                                >
                                  <X className="size-3.5 me-1" /> Reject
                                </Button>
                              </div>
                            )}
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </CardTable>
            </Card>
          )}
        </div>
      </Container>

      {/* Approve / Reject dialog */}
      <Dialog
        open={!!selected}
        onOpenChange={() => {
          if (!saving) {
            setSelected(null);
            setAction(null);
          }
        }}
      >
        <DialogContent className="max-w-lg">
          <DialogHeader>
            <DialogTitle>
              {action === 'approve'
                ? 'Approve Leave Request'
                : 'Reject Leave Request'}
            </DialogTitle>
            <DialogDescription>
              {action === 'approve'
                ? `Approving ${selected?.staff?.staff_name}'s request for ${dayCount(selected!)} days.`
                : `Provide a reason for rejecting ${selected?.staff?.staff_name}'s request.`}
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-4">
            {action === 'approve' && (
              <div className="bg-blue-50 border border-blue-100 rounded-lg p-4 space-y-3">
                <div className="flex items-start gap-2.5">
                  <AlertTriangle className="size-4 text-blue-600 mt-0.5" />
                  <div className="space-y-1">
                    <p className="text-sm font-bold text-blue-900">
                      Important Note
                    </p>
                    <p className="text-xs text-blue-800 leading-relaxed">
                      Approving this leave will automatically remove this staff
                      member from any shifts they are assigned to during this
                      period. Those shifts will become "Open" on the roster
                      board.
                    </p>
                  </div>
                </div>

                {shiftsLoading ? (
                  <div className="text-[10px] text-blue-600 animate-pulse">
                    Checking for conflicts...
                  </div>
                ) : affectedShifts.length > 0 ? (
                  <div className="space-y-2">
                    <p className="text-[10px] font-bold text-blue-900 uppercase tracking-wider">
                      Affected Shifts ({affectedShifts.length})
                    </p>
                    <div className="max-h-[120px] overflow-y-auto space-y-1.5 pr-1">
                      {affectedShifts.map((s) => (
                        <div
                          key={s.id}
                          className="flex items-center justify-between text-[10px] bg-white/50 p-1.5 rounded border border-blue-100"
                        >
                          <div className="font-medium text-gray-700">
                            {format(new Date(s.start_date), 'dd MMM')} at{' '}
                            {s.house?.house_name || 'Unknown'}
                          </div>
                          <div className="text-gray-500 italic">
                            {(s.start_time || '').slice(0, 5)} -{' '}
                            {(s.end_time || '').slice(0, 5)}
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                ) : (
                  <p className="text-[10px] text-blue-600 italic">
                    No shifts assigned during this period.
                  </p>
                )}
              </div>
            )}

            <div className="space-y-2">
              <Label htmlFor="admin-notes">
                Notes to Staff member (Optional)
              </Label>
              <Textarea
                id="admin-notes"
                placeholder={
                  action === 'reject'
                    ? 'Please explain why this request was rejected...'
                    : 'Optional message...'
                }
                value={adminNotes}
                onChange={(e) => setAdminNotes(e.target.value)}
                rows={3}
              />
            </div>

            {selected?.attachment_url && (
              <div className="flex items-center gap-2 text-sm">
                <Paperclip className="size-4 text-muted-foreground" />
                <button
                  type="button"
                  onClick={() => handleView(selected.attachment_url!)}
                  className="text-primary hover:underline font-medium cursor-pointer"
                >
                  View Attachment
                </button>
              </div>
            )}
          </div>

          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => {
                setSelected(null);
                setAction(null);
              }}
              disabled={saving}
            >
              Cancel
            </Button>
            <Button
              variant={action === 'approve' ? 'primary' : 'destructive'}
              onClick={handleAction}
              disabled={
                saving ||
                !canEdit ||
                (action === 'reject' && !adminNotes.trim())
              }
            >
              {saving
                ? 'Saving...'
                : action === 'approve'
                  ? 'Approve'
                  : 'Reject'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </Fragment>
  );
}

