import { useEffect, useMemo, useState } from 'react';
import {
  Toolbar,
  ToolbarActions,
  ToolbarDescription,
  ToolbarHeading,
  ToolbarPageTitle,
} from '@/partials/common/toolbar';
import { ArrowLeft, Loader2, Save, Settings2 } from 'lucide-react';
import { useNavigate, useParams } from 'react-router';
import { toast } from 'sonner';
import { RBAC_MODULES } from '@/config/rbac-modules';
import { ROUTES } from '@/config/routes.config';
import { getDisplayMedicationTypes } from '@/lib/medication-utils';
import {
  useAddMedicationMaster,
  useMedicationMaster,
  useMedicationTypes,
  useUpdateMedicationMaster,
} from '@/hooks/use-medications-master';
import { ACCESS_LEVEL, useRBAC } from '@/hooks/useRBAC';
import { Button } from '@/components/ui/button';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Switch } from '@/components/ui/switch';
import { Textarea } from '@/components/ui/textarea';
import { Container } from '@/components/common/container';
import { MedicationTypeMasterDialog } from './components/medication-type-master-dialog';

export function MedicationDetailPage() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const isNew = id === 'new';
  const { hasAccess } = useRBAC();

  const { data: medication, isLoading: loading } = useMedicationMaster(id);
  const { data: medicationTypes = [] } = useMedicationTypes(true); // Fetch all for manual contextual filtering
  const { mutateAsync: addMedication } = useAddMedicationMaster();
  const { mutateAsync: updateMedication } = useUpdateMedicationMaster();

  const displayTypes = useMemo(
    () => getDisplayMedicationTypes(medicationTypes, medication?.type_id),
    [medicationTypes, medication],
  );

  const [formData, setFormData] = useState({
    medication_name: '',
    brand_name: '',
    type_id: '',
    sub_class: '',
    purpose: '',
    contraindications: '',
    side_effects: '',
    interactions: '',
    is_active: true,
  });

  const [initialData, setInitialData] = useState(formData);
  const [saving, setSaving] = useState(false);
  const [typeMasterOpen, setTypeMasterOpen] = useState(false);

  const isDirty = JSON.stringify(formData) !== JSON.stringify(initialData);

  const canEdit =
    hasAccess({
      resource: RBAC_MODULES.MASTER_LISTS,
      requiredLevel: ACCESS_LEVEL.FULL,
    }) ||
    hasAccess({
      resource: RBAC_MODULES.PARTICIPANT_MEDICATIONS,
      requiredLevel: ACCESS_LEVEL.FULL,
    });

  const canManageTypes = hasAccess({
    resource: RBAC_MODULES.ACCESS_CONTROL,
    requiredLevel: ACCESS_LEVEL.FULL,
  });

  useEffect(() => {
    if (medication && !isNew) {
      const data = {
        medication_name: medication.medication_name || '',
        brand_name: medication.brand_name || '',
        type_id: medication.type_id || '',
        sub_class: medication.sub_class || '',
        purpose: medication.purpose || '',
        contraindications: medication.contraindications || '',
        side_effects: medication.side_effects || '',
        interactions: medication.interactions || '',
        is_active: medication.is_active ?? true,
      };
      setFormData(data);
      setInitialData(data);
    }
  }, [medication, isNew]);

  const handleSave = async () => {
    if (!formData.medication_name.trim()) {
      toast.error('Medication name is required');
      return;
    }

    if (!formData.type_id) {
      toast.error('Medication type is required');
      return;
    }

    setSaving(true);
    try {
      if (isNew) {
        await addMedication(formData);
        toast.success('Medication added to register');
      } else if (id) {
        await updateMedication({
          id,
          updates: formData,
          oldMedication: medication!,
        });
        toast.success('Medication updated successfully');
      }
      navigate(ROUTES.MEDICATION_REGISTER);
    } catch (error) {
      const err = error as Error;
      if (err.message === 'DUPLICATE_NAME') {
        toast.error('A medication with this name already exists');
      } else {
        toast.error('Failed to save medication: ' + err.message);
      }
    } finally {
      setSaving(false);
    }
  };

  if (loading && !isNew) {
    return (
      <div className="flex items-center justify-center py-20">
        <Loader2 className="size-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <>
      <Toolbar>
        <Container>
          <div className="flex items-center justify-between gap-5">
            <ToolbarHeading>
              <div className="flex items-center gap-3">
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => navigate(ROUTES.MEDICATION_REGISTER)}
                >
                  <ArrowLeft className="size-4 me-1.5" />
                  Back
                </Button>
                <div>
                  <ToolbarPageTitle
                    text={isNew ? 'Add Medication' : formData.medication_name}
                  />
                  <ToolbarDescription>
                    {isNew
                      ? 'Create a new entry in the medication register'
                      : 'Manage medication details and instructions'}
                  </ToolbarDescription>
                </div>
              </div>
            </ToolbarHeading>
            <ToolbarActions>
              <Button
                size="sm"
                onClick={handleSave}
                disabled={saving || !canEdit || (!isNew && !isDirty)}
              >
                {saving ? (
                  <Loader2 className="size-4 animate-spin me-1.5" />
                ) : (
                  <Save className="size-4 me-1.5" />
                )}
                {isNew ? 'Create Medication' : 'Save Changes'}
              </Button>
            </ToolbarActions>
          </div>
        </Container>
      </Toolbar>

      <Container className="py-6 lg:py-10">
        <div className="grid gap-5 lg:gap-7.5 max-w-4xl mx-auto">
          <Card>
            <CardHeader>
              <CardTitle>Medication Information</CardTitle>
              <CardDescription>
                Primary details and categorization of the medication.
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <Label htmlFor="medication_name">
                    Generic Name <span className="text-destructive">*</span>
                  </Label>
                  <Input
                    id="medication_name"
                    value={formData.medication_name}
                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        medication_name: e.target.value,
                      })
                    }
                    placeholder="e.g., Risperidone"
                    disabled={!canEdit}
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="brand_name">Brand Name (AU)</Label>
                  <Input
                    id="brand_name"
                    value={formData.brand_name}
                    onChange={(e) =>
                      setFormData({ ...formData, brand_name: e.target.value })
                    }
                    placeholder="e.g., Risperdal"
                    disabled={!canEdit}
                  />
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <div className="flex items-center justify-between">
                    <Label htmlFor="type_id">
                      Medication Type{' '}
                      <span className="text-destructive">*</span>
                    </Label>
                    {canManageTypes && (
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => setTypeMasterOpen(true)}
                        className="h-auto p-0 text-xs font-medium text-primary hover:bg-transparent hover:text-primary/80"
                      >
                        <Settings2 className="size-3 me-1.5" />
                        Manage Types
                      </Button>
                    )}
                  </div>
                  <Select
                    value={formData.type_id}
                    onValueChange={(value) =>
                      setFormData({ ...formData, type_id: value })
                    }
                    disabled={!canEdit}
                  >
                    <SelectTrigger id="type_id">
                      <SelectValue placeholder="Select type..." />
                    </SelectTrigger>
                    <SelectContent>
                      {displayTypes.map((type) => (
                        <SelectItem key={type.id} value={type.id}>
                          {type.medication_type_name}{' '}
                          {!type.is_active && '(Inactive)'}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label htmlFor="sub_class">Sub Class</Label>
                  <Input
                    id="sub_class"
                    value={formData.sub_class}
                    onChange={(e) =>
                      setFormData({ ...formData, sub_class: e.target.value })
                    }
                    placeholder="e.g., Atypical"
                    disabled={!canEdit}
                  />
                </div>
              </div>

              <div className="flex items-center justify-between rounded-lg border p-4">
                <div className="space-y-0.5">
                  <Label className="text-base">Active Status</Label>
                  <p className="text-sm text-muted-foreground">
                    Inactive medications are hidden from selection in
                    participant profiles.
                  </p>
                </div>
                <Switch
                  checked={formData.is_active}
                  onCheckedChange={(checked) =>
                    setFormData({ ...formData, is_active: checked })
                  }
                  disabled={!canEdit}
                />
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle>Clinical Guidance</CardTitle>
              <CardDescription>
                Safety information and usage instructions.
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-6">
              <div className="space-y-2">
                <Label htmlFor="purpose">Purpose (Indications)</Label>
                <Textarea
                  id="purpose"
                  value={formData.purpose}
                  onChange={(e) =>
                    setFormData({ ...formData, purpose: e.target.value })
                  }
                  placeholder="What this medication is for..."
                  rows={3}
                  disabled={!canEdit}
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="side_effects">
                  Key Side Effects to Monitor
                </Label>
                <Textarea
                  id="side_effects"
                  value={formData.side_effects}
                  onChange={(e) =>
                    setFormData({ ...formData, side_effects: e.target.value })
                  }
                  placeholder="List common side effects staff should monitor for..."
                  rows={3}
                  disabled={!canEdit}
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="contraindications">Contraindications</Label>
                <Textarea
                  id="contraindications"
                  value={formData.contraindications}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      contraindications: e.target.value,
                    })
                  }
                  placeholder="List any reasons why this medication should not be used..."
                  rows={3}
                  disabled={!canEdit}
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="interactions">
                  Never Combine With (Interactions)
                </Label>
                <Textarea
                  id="interactions"
                  value={formData.interactions}
                  onChange={(e) =>
                    setFormData({ ...formData, interactions: e.target.value })
                  }
                  placeholder="List any known drug interactions..."
                  rows={3}
                  disabled={!canEdit}
                />
              </div>
            </CardContent>
          </Card>
        </div>
      </Container>
      <MedicationTypeMasterDialog
        open={typeMasterOpen}
        onClose={() => setTypeMasterOpen(false)}
        canEdit={canManageTypes}
      />
    </>
  );
}

'use client';

import { useEffect, useMemo, useState } from 'react';
import { format, parseISO, subDays } from 'date-fns';
import { toast } from 'sonner';
import { RBAC_MODULES } from '@/config/rbac-modules';
import { useHouses } from '@/hooks/use-houses';
import { useParticipants } from '@/hooks/use-participants';
import { ShiftNote, ShiftNoteUpdateData } from '@/hooks/use-shift-notes';
import { useStaff } from '@/hooks/use-staff';
import { useStaffShifts } from '@/hooks/use-staff-shifts';
import { ACCESS_LEVEL, useRBAC } from '@/hooks/useRBAC';
import { Button } from '@/components/ui/button';
import {
  Dialog,
  DialogBody,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Label } from '@/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';

interface LinkedShiftInfo {
  id: string;
  start_time: string;
  end_time: string;
  shift_template: string;
  status: string;
}

interface EditShiftNoteDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  shiftNote: ShiftNote | null;
  onSave: (
    id: string,
    data: ShiftNoteUpdateData,
  ) => Promise<{ data: any; error: string | null }>;
  onCreate?: (
    data: ShiftNoteUpdateData,
  ) => Promise<{ data: any; error: string | null }>;
  onSuccess?: () => void;
  mode?: 'edit' | 'create';
  /** Pre-fill shift_id when launched from the roster "Write Note" button */
  initialShiftId?: string | null;
  /** Pre-fill linked shift info for display when launched from roster */
  initialLinkedShift?: LinkedShiftInfo | null;
}

export function EditShiftNoteDialog({
  open,
  onOpenChange,
  shiftNote,
  onSave,
  onCreate,
  onSuccess,
  mode = 'edit',
  initialShiftId = null,
  initialLinkedShift = null,
}: EditShiftNoteDialogProps) {
  const { data: staffData } = useStaff();
  const staff = staffData?.data || [];
  const { houses } = useHouses(0, 1000);
  const { hasAccess } = useRBAC();

  const [formData, setFormData] = useState<ShiftNoteUpdateData>({
    participant_id: null,
    staff_id: null,
    start_date: '',
    shift_time: null,
    house_id: null,
    shift_id: null,
    notes: null,
    full_note: null,
  });

  // Filter participants to only show active ones from the selected house (if any)
  const { participants, loading: loadingParticipants } = useParticipants(
    0,
    1000,
    [],
    {
      houses: formData.house_id ? [formData.house_id as string] : [],
      statuses: ['active'],
    },
  );

  // Fetch shifts for the last 14 days
  const startDate = format(subDays(new Date(), 14), 'yyyy-MM-dd');
  const endDate = format(new Date(), 'yyyy-MM-dd');
  const { shifts, loading: loadingShifts } = useStaffShifts(
    'all',
    startDate,
    endDate,
  );

  const canEdit = hasAccess({
    resource: RBAC_MODULES.PARTICIPANT_SHIFT_NOTES,
    requiredLevel: ACCESS_LEVEL.CONTEXT_READ_WRITE,
  });

  const canAdd = hasAccess({
    resource: RBAC_MODULES.PARTICIPANT_SHIFT_NOTES,
    requiredLevel: ACCESS_LEVEL.CONTEXT_READ_WRITE,
  });

  const canSubmit = mode === 'create' ? canAdd : canEdit;

  const [saving, setSaving] = useState(false);

  // Reset form when shiftNote changes or dialog opens
  useEffect(() => {
    if (open) {
      if (mode === 'create' || !shiftNote) {
        setFormData({
          participant_id: null,
          staff_id: null,
          start_date: format(new Date(), 'yyyy-MM-dd'),
          shift_time: null,
          house_id: null,
          shift_id: initialShiftId,
          notes: null,
          full_note: null,
        });

        // If we have an initialShiftId, find it in shifts and populate
        if (initialShiftId) {
          const shift = shifts.find((s) => s.id === initialShiftId);
          if (shift) {
            setFormData((prev) => ({
              ...prev,
              start_date: shift.start_date,
              shift_time: shift.start_time,
              house_id: shift.house_id,
              staff_id: shift.staff_id,
            }));
          }
        }
      } else if (shiftNote) {
        setFormData({
          participant_id: shiftNote.participant_id || null,
          staff_id: shiftNote.staff_id || null,
          start_date: shiftNote.start_date,
          shift_time: shiftNote.shift_time || null,
          house_id: shiftNote.house_id || null,
          shift_id: shiftNote.shift_id || null,
          notes: shiftNote.notes || null,
          full_note: shiftNote.full_note || null,
        });
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [shiftNote, open, mode, initialShiftId]);

  const handleShiftChange = (shiftId: string) => {
    if (shiftId === 'none') {
      setFormData((prev) => ({
        ...prev,
        shift_id: null,
        start_date: format(new Date(), 'yyyy-MM-dd'),
        shift_time: null,
        house_id: null,
        staff_id: null,
      }));
      return;
    }

    const shift = shifts.find((s) => s.id === shiftId);
    if (shift) {
      setFormData((prev) => ({
        ...prev,
        shift_id: shift.id,
        start_date: shift.start_date,
        shift_time: shift.start_time,
        house_id: shift.house_id,
        staff_id: shift.staff_id,
      }));
    }
  };

  const handleSubmit = async () => {
    if (!formData.shift_id) {
      toast.error('Please select a shift');
      return;
    }

    setSaving(true);
    const sanitizedData = {
      ...formData,
      notes: formData.notes || null,
      full_note: formData.full_note || null,
    };

    try {
      if (mode === 'create' && onCreate) {
        const { error } = await onCreate(sanitizedData);
        if (error) {
          toast.error(error);
        } else {
          toast.success('Shift note created successfully');
          onOpenChange(false);
          onSuccess?.();
        }
      } else if (shiftNote?.id) {
        const { error } = await onSave(shiftNote.id, sanitizedData);
        if (error) {
          toast.error(error);
        } else {
          toast.success('Shift note updated successfully');
          onOpenChange(false);
          onSuccess?.();
        }
      }
    } catch (err) {
      console.error('Error submitting shift note:', err);
      toast.error('Failed to save shift note');
    } finally {
      setSaving(false);
    }
  };

  const selectedStaff = staff.find((s) => s.id === formData.staff_id);
  const selectedHouse = houses.find((h) => h.id === formData.house_id);

  const isCreateMode = mode === 'create';
  const dialogTitle = isCreateMode ? 'Add Shift Note' : 'Edit Shift Note';
  const dialogDescription = isCreateMode
    ? 'Create a new shift note by selecting a shift.'
    : 'Update the shift note details below.';
  const submitButtonText = isCreateMode ? 'Create Shift Note' : 'Save Changes';

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{dialogTitle}</DialogTitle>
          <DialogDescription>{dialogDescription}</DialogDescription>
        </DialogHeader>

        <DialogBody className="space-y-5">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="shift_id">Select Shift *</Label>
              <Select
                value={formData.shift_id || 'none'}
                onValueChange={handleShiftChange}
                disabled={!canSubmit || (!isCreateMode && !!formData.shift_id)}
              >
                <SelectTrigger id="shift_id">
                  <SelectValue
                    placeholder={
                      loadingShifts ? 'Loading shifts...' : 'Select a shift'
                    }
                  />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="none">Select a shift...</SelectItem>
                  {shifts.map((s) => (
                    <SelectItem key={s.id} value={s.id}>
                      {format(parseISO(s.start_date), 'EEE, MMM d')} -{' '}
                      {s.start_time.substring(0, 5)} (
                      {s.staff_info?.staff_name || 'Unassigned'})
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="participant_id">Participant *</Label>
              <Select
                value={formData.participant_id || 'none'}
                onValueChange={(value) =>
                  setFormData((prev) => ({
                    ...prev,
                    participant_id: value === 'none' ? null : value,
                  }))
                }
                disabled={!canSubmit}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select participant" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="none">No participant selected</SelectItem>
                  {participants.map((participant) => (
                    <SelectItem key={participant.id} value={participant.id}>
                      {participant.participant_name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>

          {formData.shift_id && (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 p-4 bg-muted/30 rounded-lg border border-border/50">
              <div className="space-y-1">
                <span className="text-[10px] uppercase font-bold text-muted-foreground tracking-wider">
                  Date
                </span>
                <p className="text-sm font-medium">
                  {formData.start_date
                    ? format(parseISO(formData.start_date), 'PPP')
                    : 'N/A'}
                </p>
              </div>
              <div className="space-y-1">
                <span className="text-[10px] uppercase font-bold text-muted-foreground tracking-wider">
                  Time
                </span>
                <p className="text-sm font-medium">
                  {formData.shift_time
                    ? formData.shift_time.substring(0, 5)
                    : 'N/A'}
                </p>
              </div>
              <div className="space-y-1">
                <span className="text-[10px] uppercase font-bold text-muted-foreground tracking-wider">
                  Staff
                </span>
                <p className="text-sm font-medium">
                  {selectedStaff?.staff_name || 'N/A'}
                </p>
              </div>
              <div className="space-y-1">
                <span className="text-[10px] uppercase font-bold text-muted-foreground tracking-wider">
                  House
                </span>
                <p className="text-sm font-medium">
                  {selectedHouse?.house_name || 'N/A'}
                </p>
              </div>
            </div>
          )}

          <div className="space-y-2">
            <Label htmlFor="notes">Summary</Label>
            <Textarea
              id="notes"
              placeholder="Brief summary of the shift note..."
              value={formData.notes || ''}
              onChange={(e) =>
                setFormData((prev) => ({
                  ...prev,
                  notes: e.target.value || null,
                }))
              }
              rows={2}
              disabled={!canSubmit}
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="full_note">Full Note</Label>
            <Textarea
              id="full_note"
              placeholder="Enter detailed shift note here..."
              value={formData.full_note || ''}
              onChange={(e) =>
                setFormData((prev) => ({
                  ...prev,
                  full_note: e.target.value || null,
                }))
              }
              rows={5}
              disabled={!canSubmit}
            />
          </div>
        </DialogBody>

        <DialogFooter>
          <Button
            variant="outline"
            onClick={() => onOpenChange(false)}
            disabled={saving}
          >
            Cancel
          </Button>
          <Button onClick={handleSubmit} disabled={saving || !canSubmit}>
            {saving ? 'Saving...' : submitButtonText}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

